    req = urllib.request.Request("http://127.0.0.1:18787/api", data=body, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=5) as r:
            print(op, r.read().decode())
    except Exception as e:
        print(op, "ERROR", e)
"]}

